def put(n,d):(HERE/n).write_text(json.dumps(d,indent=2)+'\n',encoding='utf8')
def main():
    specs=[('R-HH-N1570','WG14 N1570 C11 committee draft','WG14','2011-04-12 draft',2011,'standard','n1570.pdf','https://www.open-std.org/jtc1/sc22/wg14/www/docs/n1570.pdf',['5.1.1.3p1-2 and footnote9: required diagnostics and permitted continuing translation','6.5.2.2p1-2: prototyped call constraints','6.5.6p7-8: array pointer extent and forbidden one-past dereference','6.7p4: compatible declarations in the same scope','6.7.4p1-11: inline restrictions, internal linkage, external definitions and examples','6.9p3-5: internal and external definition obligations']),('R-HH-GCC','GCC Using the GNU Compiler Collection: An Inline Function is As Fast As a Macro','GNU Project','Live manual captured2026-10-18',2026,'documentation','inline.html','https://gcc.gnu.org/onlinedocs/gcc/Inline.html',['Complete inline section: three semantic modes, static-inline address/emission, optimization and historical GNU extern-inline behavior']),('R-HH-CLANG','Clang Static Analyzer: security.ArrayBound','LLVM Project','Live manual captured2026-10-18',2026,'documentation','checkers.html','https://clang.llvm.org/docs/analyzer/checkers.html',['Section1.1.7.1 security.ArrayBound: region bounds, uncertain-index assumption, taint distinction and former ArrayBoundV2 name'])]
    records=[]
